mapper.update:
UPDATE ${table}
SET status = #{row.status},
    owner_token = #{row.ownerToken},
    version = #{row.version},
    processing_expire_at = #{row.processingExpireAt},
    failure_code = NULL,
    failure_message = NULL,
    failure_retryable = FALSE,
    result_payload = NULL,
    completed_at = NULL,
    updated_at = #{row.updatedAt}
WHERE store_name = #{row.storeName}
  AND namespace = #{row.namespace}
  AND idempotency_key = #{row.idempotencyKey}
  AND version = #{expectedVersion}

UPDATE ${table}
SET window_expire_at = #{row.windowExpireAt},
    retention_expire_at = #{row.retentionExpireAt},
    updated_at = #{row.updatedAt}
WHERE store_name = #{row.storeName}
  AND namespace = #{row.namespace}
  AND idempotency_key = #{row.idempotencyKey}
  AND version = #{expectedVersion}

UPDATE ${table}
SET status = #{row.status},
    result_payload = #{row.resultPayload},
    failure_code = NULL,
    failure_message = NULL,
    failure_retryable = FALSE,
    processing_expire_at = NULL,
    completed_at = #{row.completedAt},
    updated_at = #{row.updatedAt},
    window_expire_at = #{row.windowExpireAt},
    retention_expire_at = #{row.retentionExpireAt}
WHERE store_name = #{row.storeName}
  AND namespace = #{row.namespace}
  AND idempotency_key = #{row.idempotencyKey}
  AND status = 'PROCESSING'
  AND owner_token = #{expectedOwner}
  AND version = #{expectedVersion}

UPDATE ${table}
SET status = 'FAILED',
    failure_code = #{row.failureCode},
    failure_message = #{row.failureMessage},
    failure_retryable = #{row.failureRetryable},
    processing_expire_at = NULL,
    updated_at = #{row.updatedAt},
    window_expire_at = #{row.windowExpireAt},
    retention_expire_at = #{row.retentionExpireAt}
WHERE store_name = #{row.storeName}
  AND namespace = #{row.namespace}
  AND idempotency_key = #{row.idempotencyKey}
  AND status = 'PROCESSING'
  AND owner_token = #{expectedOwner}
  AND version = #{expectedVersion}

mapper.select:
SELECT 
FROM ${table}
WHERE store_name = #{storeName}
  AND scan_bucket = #{scanBucket}
  AND recovery_mode = 'EXTERNAL_TASK'
  AND namespace = #{namespace}
  AND (window_expire_at IS NULL OR window_expire_at > #{now})
  AND ((status = 'PROCESSING' AND processing_expire_at IS NOT NULL AND processing_expire_at <= #{now})
    OR (status = 'FAILED' AND failure_retryable = TRUE))
ORDER BY processing_expire_at ASC, id ASC
LIMIT #{limit}
